// absolutizedAlternates reads the first line of the wrapped alternates file
// (capped at maxAlternatesReadBytes) and returns it with a relative entry
// resolved against <root>/objects. ok is false when the file is
// missing/unreadable, empty, or the entry is already absolute, in which case
// the caller serves the original file.
func (fs *alternatesRewriteFS) absolutizedAlternates() (string, bool) {
	f, err := fs.Filesystem.Open(filepath.FromSlash(alternatesFilePath))
	if err != nil {
		return "", false
	}
	defer func() { _ = f.Close() }()

	reader := bufio.NewReader(io.LimitReader(f, maxAlternatesReadBytes))
	line, err := reader.ReadString('\n')
	if err != nil && !errors.Is(err, io.EOF) {
		return "", false
	}
	trimmed := strings.TrimSpace(line)
	if trimmed == "" || filepath.IsAbs(trimmed) || filepath.VolumeName(trimmed) != "" {
		return "", false
	}

	objectsBase := filepath.Join(fs.Root(), "objects")
	return filepath.Clean(filepath.Join(objectsBase, filepath.FromSlash(trimmed))), true
}

